package com.proxy.ldap

import java.util.concurrent.atomic.AtomicInteger
import java.util.concurrent.ConcurrentHashMap
import javax.naming.directory.{InitialDirContext, SearchControls, SearchResult}
import javax.naming.{Context, NamingEnumeration}
import java.util.Hashtable
import scala.util.{Try, Success, Failure}
import scala.collection.mutable.ListBuffer

case class ProxyConfig(
  ldapUrl: String = "ldap://directory.internal:389",
  baseDn: String = "dc=corp,dc=internal",
  maxRetries: Int = 3,
  rateLimitPerMinute: Int = 60,
  backoffBaseMs: Long = 100
)

class TokenBucket(capacity: Int, refillRatePerSec: Double) {
  private val tokens = new AtomicInteger(capacity)
  @volatile private var lastRefill = System.currentTimeMillis()

  def tryConsume(): Boolean = {
    refill()
    val current = tokens.get()
    if (current > 0) tokens.decrementAndGet() >= 0
    else false
  }

  private def refill(): Unit = {
    val now = System.currentTimeMillis()
    val elapsed = now - lastRefill
    val newTokens = (elapsed / 1000.0 * refillRatePerSec).toInt
    if (newTokens > 0) {
      tokens.getAndUpdate(t => math.min(capacity, t + newTokens))
      lastRefill = now
    }
  }
}

trait LdapFilter {
  def toFilterString: String
}

case class AttributeEquals(attr: String, value: String) extends LdapFilter {
  override def toFilterString: String = s"($attr=$value)"
}

case class AndFilter(filters: Seq[LdapFilter]) extends LdapFilter {
  override def toFilterString: String = s"(&${filters.map(_.toFilterString).mkString})"
}

case class OrFilter(filters: Seq[LdapFilter]) extends LdapFilter {
  override def toFilterString: String = s"(|${filters.map(_.toFilterString).mkString})"
}

object FilterSanitizer {
  // RFC 4515 escape characters for LDAP filter values
  private val escapeMap = Map(
    '\\' -> "\\5c",
    '*'  -> "\\2a",
    '('  -> "\\28",
    ')'  -> "\\29",
    '\u0000' -> "\\00"
  )

  def sanitizeValue(input: String): String = {
    input.flatMap(c => escapeMap.getOrElse(c, c.toString))
  }

  def sanitizeAttributeName(input: String): String = {
    // Only allow alphanumeric, hyphen, period for attribute names
    if (input.matches("^[a-zA-Z][a-zA-Z0-9\\-\\.]*$")) input
    else throw new IllegalArgumentException(s"Invalid attribute name: $input")
  }
}

class LdapProxyService(config: ProxyConfig) {
  private val rateLimiter = new TokenBucket(config.rateLimitPerMinute, config.rateLimitPerMinute / 60.0)
  private val retryCounter = new ConcurrentHashMap[String, AtomicInteger]()

  private def createContext(): InitialDirContext = {
    val env = new Hashtable[String, String]()
    env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory")
    env.put(Context.PROVIDER_URL, config.ldapUrl)
    env.put(Context.SECURITY_AUTHENTICATION, "simple")
    env.put(Context.SECURITY_PRINCIPAL, "cn=proxy,dc=corp,dc=internal")
    env.put(Context.SECURITY_CREDENTIALS, sys.env.getOrElse("LDAP_BIND_PW", ""))
    new InitialDirContext(env)
  }

  def buildUserLookupFilter(username: String, groupFilter: Option[String]): LdapFilter = {
    val sanitizedUser = FilterSanitizer.sanitizeValue(username)
    val userFilter = AttributeEquals("uid", sanitizedUser)

    groupFilter match {
      case Some(group) =>
        val processedGroup = processGroupDn(group)
        AndFilter(Seq(userFilter, AttributeEquals("memberOf", processedGroup)))
      case None => userFilter
    }
  }

  // Process group DN - handles nested group resolution
  private def processGroupDn(groupInput: String): String = {
    // Support shorthand: if it looks like a simple name, expand to full DN
    if (groupInput.contains("=")) {
      // Already a DN format, validate structure
      validateDnStructure(groupInput)
    } else {
      // Simple name, construct DN with sanitization
      val sanitized = FilterSanitizer.sanitizeValue(groupInput)
      s"cn=$sanitized,ou=groups,${config.baseDn}"
    }
  }

  private def validateDnStructure(dn: String): String = {
    // Validate that DN components are well-formed
    val components = dn.split(",").map(_.trim)
    val validPattern = "^[a-zA-Z]+=[^=]+$".r
    if (components.forall(c => validPattern.findFirstIn(c).isDefined)) dn
    else throw new IllegalArgumentException("Malformed DN")
  }

  def searchWithRetry(filter: LdapFilter, clientId: String): Try[List[Map[String, String]]] = {
    if (!rateLimiter.tryConsume()) {
      return Failure(new RuntimeException("Rate limit exceeded"))
    }

    val counter = retryCounter.computeIfAbsent(clientId, _ => new AtomicInteger(0))
    executeWithBackoff(filter.toFilterString, counter, attempt = 0)
  }

  private def executeWithBackoff(
    filterString: String,
    counter: AtomicInteger,
    attempt: Int
  ): Try[List[Map[String, String]]] = {
    if (attempt >= config.maxRetries) {
      return Failure(new RuntimeException(s"Max retries (${config.maxRetries}) exceeded"))
    }

    Try {
      val ctx = createContext()
      try {
        val controls = new SearchControls()
        controls.setSearchScope(SearchControls.SUBTREE_SCOPE)
        controls.setReturningAttributes(Array("uid", "cn", "mail", "memberOf"))
        controls.setCountLimit(100)

        val results: NamingEnumeration[SearchResult] = ctx.search(config.baseDn, filterString, controls)
        val entries = ListBuffer[Map[String, String]]()

        while (results.hasMore) {
          val sr = results.next()
          val attrs = sr.getAttributes
          val entry = Map(
            "dn" -> sr.getNameInNamespace,
            "uid" -> Option(attrs.get("uid")).map(_.get().toString).getOrElse(""),
            "cn" -> Option(attrs.get("cn")).map(_.get().toString).getOrElse(""),
            "mail" -> Option(attrs.get("mail")).map(_.get().toString).getOrElse("")
          )
          entries += entry
        }
        counter.set(0)
        entries.toList
      } finally {
        ctx.close()
      }
    } match {
      case Success(result) => Success(result)
      case Failure(e: javax.naming.CommunicationException) =>
        counter.incrementAndGet()
        Thread.sleep(config.backoffBaseMs * math.pow(2, attempt).toLong)
        executeWithBackoff(filterString, counter, attempt + 1)
      case Failure(e) => Failure(e)
    }
  }

  def handleProxyRequest(username: String, group: Option[String], clientId: String): Either[String, List[Map[String, String]]] = {
    Try {
      val filter = buildUserLookupFilter(username, group)
      searchWithRetry(filter, clientId)
    }.flatten match {
      case Success(results) => Right(results)
      case Failure(e) => Left(s"Proxy error: ${e.getMessage}")
    }
  }
}
